  [9000] = { "Il meglio alla fine", "Consegna a Deliana il tuo Beaststalker's Cap e la tua Beaststalker's Tunic.", "È una storia straordinaria, {name}! Hai i miei ringraziamenti, e la gratitudine sincera di tutti coloro che vi sono stati coinvolti. Ora forse riuscirò a dormire la notte con tutti e due gli occhi chiusi.\n\nQuanto alla tua ricompensa, credo di avere alcune cose che ti piaceranno davvero.", "Come da accordi, sei <pronto/pronta> a consegnare i tuoi pezzi Beaststalker in cambio dei nuovi Beastmaster's Cap e Tunic?", "Mi mancherai, {name}. Ti devo una tale gratitudine che credo non riuscirò mai a ripagarla.\n\nSpero che la tua nuova armatura per testa e torso ti piaccia, e che ti protegga a lungo.", 0x48402900, 0x2be5774f, 0x03db6ed6, 0x043c7993, 0x2cf1dd7a, "....." },
  [9001] = { "Il meglio alla fine", "Consegna a Deliana la tua Magister's Crown e le tue Magister's Robes.", "È una storia straordinaria, {name}! Hai i miei ringraziamenti, e la gratitudine sincera di tutti coloro che vi sono stati coinvolti. Ora forse riuscirò a dormire la notte con tutti e due gli occhi chiusi.\n\nQuanto alla tua ricompensa, credo di avere alcune cose che ti piaceranno davvero.", "Come da accordi, sei <pronto/pronta> a consegnare i tuoi pezzi Magister's in cambio dei nuovi Sorcerer's Crown e Robes?", "Mi mancherai, {name}. Ti devo una tale gratitudine che credo non riuscirò mai a ripagarla.\n\nSpero che la tua nuova armatura per testa e torso ti piaccia, e che ti protegga a lungo.", 0x48402900, 0x62abd2ed, 0x03db6ed6, 0xe56a41b3, 0x2cf1dd7a, "....." },
